cd data && python3 -c "
import pandas as pd
df=pd.read_csv('CMHthr.csv'); df['date']=pd.to_datetime(df.date); df=df.sort_values(['day','date'])
def ev(g, mode):
    m=-999; out=[]
    for t in g.temp:
        if (t>m if mode=='strict' else t>=m):
            out.append(True); m=t
        else: out.append(False)
    return pd.Series(out,index=g.index)
for mode in ['strict','ties']:
    e=df.groupby('day',group_keys=False).apply(lambda g: ev(g,mode))
    evdf=df[e].copy(); evdf['ym']=evdf.date.dt.to_period('M')
    print(mode, 'total',e.sum(),'2007+',evdf[evdf.date.dt.year>=2007].shape[0])
"

